import { EventEmitter } from 'events';
import * as net from 'net';
import * as http from 'http';

interface QueryResult {
  rows: any[];
  affectedRows: number;
}

interface ConnectionConfig {
  host: string;
  port: number;
  database: string;
  authToken: string;
  keepAlive: boolean;
}

// Reject any value that would allow CRLF-based HTTP header injection.
function assertNoCRLF(name: string, value: string): void {
  if (/[\r\n]/.test(value)) {
    throw new Error(`Invalid characters (CR/LF) in ${name}`);
  }
}

class HTTPDBProtocol {
  private socket: net.Socket | null = null;
  private pendingRequests: Map<string, { resolve: Function; reject: Function }> = new Map();
  private buffer: string = '';
  private config: ConnectionConfig;
  private requestCounter: number = 0;

  constructor(config: ConnectionConfig) {
    // Validate header-embedded config values up front to prevent header injection.
    assertNoCRLF('host', config.host);
    assertNoCRLF('authToken', config.authToken);
    if (!Number.isInteger(config.port) || config.port <= 0 || config.port > 65535) {
      throw new Error('Invalid port');
    }
    this.config = config;
  }

  async connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      this.socket = net.createConnection({
        host: this.config.host,
        port: this.config.port
      }, () => resolve());
      this.socket.on('data', (chunk) => this.handleData(chunk));
      this.socket.on('error', reject);
    });
  }

  private handleData(chunk: Buffer): void {
    this.buffer += chunk.toString('utf-8');
    this.processBuffer();
  }

  private processBuffer(): void {
    const headerEnd = this.buffer.indexOf('\r\n\r\n');
    if (headerEnd === -1) return;

    const headers = this.buffer.substring(0, headerEnd);
    const contentLengthMatch = headers.match(/Content-Length:\s*(\d+)/i);
    if (!contentLengthMatch) return;

    const contentLength = parseInt(contentLengthMatch[1], 10);
    const bodyStart = headerEnd + 4;
    const bodyEnd = bodyStart + contentLength;

    if (this.buffer.length < bodyEnd) return;

    const body = this.buffer.substring(bodyStart, bodyEnd);
    this.buffer = this.buffer.substring(bodyEnd);

    const requestIdMatch = headers.match(/X-Request-Id:\s*([\w-]+)/i);
    if (requestIdMatch) {
      const pending = this.pendingRequests.get(requestIdMatch[1]);
      if (pending) {
        this.pendingRequests.delete(requestIdMatch[1]);
        try {
          pending.resolve(JSON.parse(body));
        } catch (err) {
          // Malformed response body must reject the pending request,
          // not throw an unhandled exception inside the data handler.
          pending.reject(err instanceof Error ? err : new Error('Invalid response body'));
        }
      }
    }

    if (this.buffer.length > 0) this.processBuffer();
  }

  private buildRequest(method: string, path: string, body: string, requestId: string): string {
    // Guard against CRLF injection through the request line and request id.
    assertNoCRLF('method', method);
    assertNoCRLF('path', path);
    assertNoCRLF('requestId', requestId);

    const bodyBuffer = Buffer.from(body, 'utf-8');
    const headers = [
      `${method} ${path} HTTP/1.1`,
      `Host: ${this.config.host}:${this.config.port}`,
      `Authorization: Bearer ${this.config.authToken}`,
      `Content-Type: application/json`,
      `X-Request-Id: ${requestId}`,
      `Content-Length: ${bodyBuffer.byteLength}`,
    ];

    if (this.config.keepAlive) {
      headers.push('Connection: keep-alive');
    }

    return headers.join('\r\n') + '\r\n\r\n' + body;
  }

  async query(sql: string, params: any[] = []): Promise<QueryResult> {
    const requestId = `req-${++this.requestCounter}-${Date.now()}`;
    const body = JSON.stringify({ sql, params, database: this.config.database });
    const rawRequest = this.buildRequest('POST', '/v1/query', body, requestId);

    return new Promise((resolve, reject) => {
      this.pendingRequests.set(requestId, { resolve, reject });
      this.socket!.write(rawRequest);
    });
  }

  async transaction(queries: string[]): Promise<QueryResult[]> {
    const results: QueryResult[] = [];
    const txId = `tx-${++this.requestCounter}-${Date.now()}`;

    const beginBody = JSON.stringify({ action: 'begin', txId });
    const beginReq = this.buildRequest('POST', '/v1/transaction', beginBody, txId + '-begin');

    await new Promise<void>((resolve, reject) => {
      this.pendingRequests.set(txId + '-begin', { resolve, reject });
      this.socket!.write(beginReq);
    });

    for (let i = 0; i < queries.length; i++) {
      const qBody = JSON.stringify({ sql: queries[i], txId });
      const qReqId = `${txId}-q${i}`;
      const qReq = this.buildRequest('POST', '/v1/transaction/exec', qBody, qReqId);

      const result = await new Promise<QueryResult>((resolve, reject) => {
        this.pendingRequests.set(qReqId, { resolve, reject });
        this.socket!.write(qReq);
      });
      results.push(result);
    }

    const commitBody = JSON.stringify({ action: 'commit', txId });
    const commitReq = this.buildRequest('POST', '/v1/transaction', commitBody, txId + '-commit');
    await new Promise<void>((resolve, reject) => {
      this.pendingRequests.set(txId + '-commit', { resolve, reject });
      this.socket!.write(commitReq);
    });

    return results;
  }

  async close(): Promise<void> {
    this.socket?.destroy();
    this.pendingRequests.clear();
  }
}

export class DatabaseDriver extends EventEmitter {
  private protocol: HTTPDBProtocol;
  private connected: boolean = false;

  constructor(config: ConnectionConfig) {
    super();
    this.protocol = new HTTPDBProtocol(config);
  }

  async initialize(): Promise<void> {
    await this.protocol.connect();
    this.connected = true;
    this.emit('connected');
  }

  async execute(sql: string, params?: any[]): Promise<QueryResult> {
    if (!this.connected) throw new Error('Not connected');
    return this.protocol.query(sql, params);
  }

  async executeTransaction(queries: string[]): Promise<QueryResult[]> {
    if (!this.connected) throw new Error('Not connected');
    return this.protocol.transaction(queries);
  }

  async disconnect(): Promise<void> {
    await this.protocol.close();
    this.connected = false;
    this.emit('disconnected');
  }
}
